CREATE TEMPORARY VIEW dim_item_${grass_region_without_quote} AS
SELECT
    item_id
    ,SPLIT(images,',')[0] AS image_id
    ,shop_id
FROM
    srdi_mart.dim_sr_data_warehouse_item
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
GROUP BY
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_smart_ui_1d_${grass_region_without_quote} AS
SELECT
    a.item_id AS item_id
    ,a.image_id AS image_id
    ,MAX(b.shop_id) AS shop_id
    ,MAX(IF(c.image_id IS NOT NULL, TRUE, FALSE)) AS is_origin_cover
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
FROM
    srdi_mart.dws_sr_data_warehouse_search_smart_ui_metrics_1d a
LEFT JOIN
    dim_item_${grass_region_without_quote} b
ON
    COALESCE(a.item_id, -1) = COALESCE(b.item_id, -1)
LEFT JOIN
    dim_item_${grass_region_without_quote} c
ON
    COALESCE(a.item_id, -1) = COALESCE(c.item_id, -1)
    AND COALESCE(a.image_id, 'NULL') = COALESCE(c.image_id, 'NULL')
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND target_type = 'item'
GROUP BY
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW smart_ui_1d_item_id_${grass_region_without_quote} AS
SELECT
    item_id
FROM
    dws_smart_ui_1d_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW smart_ui_180d_${grass_region_without_quote} AS
SELECT
    a.item_id AS item_id
    ,a.image_id AS image_id
    ,MAX(b.is_origin_cover) AS is_origin_cover
    ,SUM(a.imp_cnt) AS imp_cnt_180d
FROM
    srdi_mart.dws_sr_data_warehouse_search_smart_ui_metrics_1d a
JOIN
    dws_smart_ui_1d_${grass_region_without_quote} b
ON
    COALESCE(a.item_id, -1) = COALESCE(b.item_id, -1)
    AND COALESCE(a.image_id, 'NULL') = COALESCE(b.image_id, 'NULL')
WHERE
    a.grass_region = ${grass_region}
    AND a.local_date BETWEEN DATE_SUB(${local_date}, 179) AND ${local_date}
    AND a.target_type = 'item'
GROUP BY 
    1,2;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_item_exp_status_${grass_region_without_quote} AS
SELECT
    item_id
    ,CASE
        WHEN MAX(IF(is_origin_cover = TRUE, imp_cnt_180d, 0)) >= 100
            AND MAX(IF(is_origin_cover = FALSE, imp_cnt_180d, 0)) >= 100
        THEN 1
        ELSE 0
    END AS exp_status
FROM
    smart_ui_180d_${grass_region_without_quote}
GROUP BY
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_smart_ui_30d_image_level_metrics_${grass_region_without_quote} AS
