CREATE TEMPORARY VIEW dws_smart_ui_30d_item_level_metrics_${grass_region_without_quote} AS
SELECT
    a.item_id AS item_id
    ,SUM(imp_cnt) AS item_imp_cnt_30d
    ,SUM(click_cnt) AS item_click_cnt_30d
