CREATE TEMPORARY VIEW dws_item_image_${grass_region_without_quote} AS
SELECT
    a.item_id AS item_id
    ,shop_id
    ,a.image_id AS image_id
    ,imp_cnt
    ,click_cnt
    ,IF(imp_cnt > 0, click_cnt * 1.0 / imp_cnt, 0) AS image_ctr
    ,DENSE_RANK() OVER (PARTITION BY a.item_id ORDER BY imp_cnt DESC) AS image_imp_rank_dense
    ,ROW_NUMBER() OVER (PARTITION BY a.item_id ORDER BY imp_cnt DESC, IF(imp_cnt > 0, click_cnt * 1.0 / imp_cnt, 0) DESC, a.image_id DESC) AS image_imp_rank_row_number
    ,DENSE_RANK() OVER (PARTITION BY a.item_id ORDER BY IF(imp_cnt > 0, click_cnt * 1.0 / imp_cnt, 0) DESC) AS image_ctr_rank_dense
    ,ROW_NUMBER() OVER (PARTITION BY a.item_id ORDER BY IF(imp_cnt > 0, click_cnt * 1.0 / imp_cnt, 0) DESC) AS image_ctr_rank_row_number
    ,order_cnt
    ,gmv
    ,is_origin_cover
    ,exp_status
    ,imp_cnt_30d
    ,click_cnt_30d
    ,1.0 * click_cnt_30d / imp_cnt_30d AS image_ctr_30d
    ,item_imp_cnt_30d
    ,item_click_cnt_30d
    ,1.0 * item_click_cnt_30d / item_imp_cnt_30d AS item_ctr_30d
FROM
    dws_smart_ui_1d_${grass_region_without_quote} a
LEFT JOIN
    dws_item_exp_status_${grass_region_without_quote} b
ON
    COALESCE(a.item_id, -1) = COALESCE(b.item_id, -1)
LEFT JOIN
    dws_smart_ui_30d_image_level_metrics_${grass_region_without_quote} c
ON
    COALESCE(a.item_id, -1) = COALESCE(c.item_id, -1)
    AND COALESCE(a.image_id, 'NULL') = COALESCE(c.image_id, 'NULL')
LEFT JOIN
    dws_smart_ui_30d_item_level_metrics_${grass_region_without_quote} d
ON
    COALESCE(a.item_id, -1) = COALESCE(d.item_id, -1);

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.ads_sr_data_warehouse_platform_smart_ui_best_performance_1d
PARTITION (
    grass_region = ${grass_region}
    ,local_date = ${local_date}
    ,scenario_tag
)
SELECT
    item_id
    ,shop_id
    ,image_id
    ,CASE
        WHEN exp_status = 1
            AND image_imp_rank_row_number = 1
        THEN TRUE
        ELSE FALSE
    END is_best_image
    ,imp_cnt
    ,image_imp_rank_dense
    ,image_imp_rank_row_number
    ,click_cnt
    ,image_ctr
    ,image_ctr_rank_dense
    ,image_ctr_rank_row_number
    ,order_cnt
    ,gmv
    ,is_origin_cover
    ,exp_status
    ,imp_cnt_30d
    ,click_cnt_30d
    ,image_ctr_30d
    ,item_imp_cnt_30d
    ,item_click_cnt_30d
    ,item_ctr_30d
    ,'Global Search' AS scenario_tag
FROM
    dws_item_image_${grass_region_without_quote};
